//! ArmourClass: ARMOUR "class" (sheet T00033).
//!
//! Generated by `python tools/gen_enum.py T00033 ArmourClass ...` from sheet/enums.tsv; do not edit.

/// @type ArmourClass
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(i32)]
pub enum ArmourClass {
    GearCloth = 0,
    GearLight = 1,
    GearMedium = 2,
    GearHeavy = 3,
    GearMax = 4,
}

impl ArmourClass {
    pub fn from_i32(v: i32) -> Option<Self> {
        Some(match v {
            0 => Self::GearCloth,
            1 => Self::GearLight,
            2 => Self::GearMedium,
            3 => Self::GearHeavy,
            4 => Self::GearMax,
            _ => return None,
        })
    }

    /// The name as in the sheet (the FCS schema name).
    pub fn name(self) -> &'static str {
        match self {
            Self::GearCloth => "GEAR_CLOTH",
            Self::GearLight => "GEAR_LIGHT",
            Self::GearMedium => "GEAR_MEDIUM",
            Self::GearHeavy => "GEAR_HEAVY",
            Self::GearMax => "GEAR_MAX",
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_sheet() {
        let sheet = include_str!("../../sheet/enums.tsv");
        let mut n = 0;
        for line in sheet.lines().filter(|l| l.starts_with("T00033\t")) {
            let f: Vec<&str> = line.split('\t').collect();
            let v: i32 = f[2].parse().unwrap();
            let t = ArmourClass::from_i32(v)
                .unwrap_or_else(|| panic!("sheet value {v} missing in enum"));
            assert_eq!(t.name(), f[1]);
            assert_eq!(t as i32, v);
            n += 1;
        }
        assert_eq!(n, 5, "enum and sheet differ in size");
    }
}
